#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <signal.h>
#include <unistd.h>
#include <sys/socket.h>
#include <netinet/in.h>
#include <pthread.h>

#define MAX_LAYERS 16
#define TENSOR_BUF_SIZE 4096
#define MODEL_NAME_LEN 64

typedef struct {
    float weights[TENSOR_BUF_SIZE];
    int input_dim;
    int output_dim;
    char activation[16];
} Layer;

typedef enum {
    CLEANUP_DEFAULT = 0,
    CLEANUP_FLUSH_LOGS = 1,
    CLEANUP_SAVE_STATE = 2
} CleanupMode;

typedef struct {
    Layer layers[MAX_LAYERS];
    int num_layers;
    char model_name[MODEL_NAME_LEN];
    volatile int shutting_down;
    CleanupMode cleanup_mode;
} InferenceServer;

static InferenceServer *g_server = NULL;

static void apply_relu(float *data, int len) {
    for (int i = 0; i < len; i++)
        if (data[i] < 0.0f) data[i] = 0.0f;
}

static void apply_sigmoid(float *data, int len) {
    for (int i = 0; i < len; i++)
        data[i] = 1.0f / (1.0f + __builtin_expf(-data[i]));
}

static float* forward_pass(InferenceServer *srv, float *input, int input_len) {
    float *current = input;
    int current_len = input_len;

    for (int l = 0; l < srv->num_layers && !srv->shutting_down; l++) {
        Layer *layer = &srv->layers[l];
        if (current_len != layer->input_dim) return NULL;

        float *output = (float*)malloc(layer->output_dim * sizeof(float));
        if (!output) return NULL;

        for (int o = 0; o < layer->output_dim; o++) {
            output[o] = 0.0f;
            for (int i = 0; i < layer->input_dim; i++)
                output[o] += current[i] * layer->weights[o * layer->input_dim + i];
        }

        if (strcmp(layer->activation, "relu") == 0)
            apply_relu(output, layer->output_dim);
        else if (strcmp(layer->activation, "sigmoid") == 0)
            apply_sigmoid(output, layer->output_dim);

        if (current != input) free(current);
        current = output;
        current_len = layer->output_dim;
    }
    return current;
}

static void perform_cleanup(InferenceServer *srv) {
    switch (srv->cleanup_mode) {
        case CLEANUP_FLUSH_LOGS:
            /* flush any pending log buffers */
            fflush(stdout);
            fflush(stderr);
            break;
        case CLEANUP_SAVE_STATE:
            /* zero out weights for security */
            memset(srv->layers, 0, sizeof(srv->layers));
            break;
        case CLEANUP_DEFAULT:
        default:
            memset(srv->layers, 0, sizeof(srv->layers));
            break;
    }
}

static void graceful_shutdown(int sig) {
    if (g_server) {
        g_server->shutting_down = 1;
        perform_cleanup(g_server);
    }
}

static int load_model_config(InferenceServer *srv, const char *config, size_t config_len) {
    if (config_len < 8) return -1;

    int num_layers = *(int*)config;
    if (num_layers < 0 || num_layers > MAX_LAYERS) return -1;

    srv->num_layers = num_layers;
    size_t offset = sizeof(int);

    /* Read model name - length prefixed */
    if (offset + sizeof(int) > config_len) return -1;
    int name_len = *(int*)(config + offset);
    offset += sizeof(int);

    if (name_len > 0 && name_len < MODEL_NAME_LEN) {
        if (offset + name_len > config_len) return -1;
        memcpy(srv->model_name, config + offset, name_len);
        srv->model_name[name_len] = '\0';
        offset += name_len;
    }

    /* Read cleanup mode - validated enum */
    if (offset + sizeof(int) > config_len) return -1;
    int mode = *(int*)(config + offset);
    offset += sizeof(int);

    if (mode >= CLEANUP_DEFAULT && mode <= CLEANUP_SAVE_STATE) {
        srv->cleanup_mode = (CleanupMode)mode;
    } else {
        srv->cleanup_mode = CLEANUP_DEFAULT;
    }

    /* Load layer configurations */
    for (int l = 0; l < num_layers && offset < config_len; l++) {
        if (offset + 2 * sizeof(int) > config_len) break;
        srv->layers[l].input_dim = *(int*)(config + offset);
        offset += sizeof(int);
        srv->layers[l].output_dim = *(int*)(config + offset);
        offset += sizeof(int);

        if (srv->layers[l].input_dim <= 0 || srv->layers[l].output_dim <= 0)
            return -1;
        if (srv->layers[l].input_dim > 64 || srv->layers[l].output_dim > 64)
            return -1;

        strncpy(srv->layers[l].activation, "relu", 15);
    }

    return 0;
}

static void handle_client(InferenceServer *srv, int client_fd) {
    char buf[8192];
    ssize_t n = read(client_fd, buf, sizeof(buf));
    if (n <= 0) return;

    /* First byte: command type */
    if (buf[0] == 0x01) {
        /* Model config load */
        if (load_model_config(srv, buf + 1, n - 1) == 0)
            write(client_fd, "OK\n", 3);
        else
            write(client_fd, "ERR\n", 4);
    } else if (buf[0] == 0x02) {
        /* Inference request */
        /* Ensure the length prefix is fully present before reading it,
           and that a model with at least one layer has been loaded. */
        if (n < 5 || srv->num_layers <= 0)
            return;
        int input_len = *(int*)(buf + 1);
        if (input_len > 0 && input_len <= 64 && (size_t)(5 + input_len * 4) <= (size_t)n) {
            float *input = (float*)(buf + 5);
            float *result = forward_pass(srv, input, input_len);
            if (result) {
                write(client_fd, result, srv->layers[srv->num_layers-1].output_dim * sizeof(float));
                if (result != input) free(result);
            }
        }
    } else if (buf[0] == 0x03) {
        /* Graceful shutdown request */
        raise(SIGTERM);
    }
}

int main(int argc, char **argv) {
    InferenceServer *srv = (InferenceServer*)calloc(1, sizeof(InferenceServer));
    if (!srv) return 1;

    srv->cleanup_mode = CLEANUP_DEFAULT;
    g_server = srv;

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = graceful_shutdown;
    sigaction(SIGTERM, &sa, NULL);
    sigaction(SIGINT, &sa, NULL);

    int sock = socket(AF_INET, SOCK_STREAM, 0);
    int opt = 1;
    setsockopt(sock, SOL_SOCKET, SO_REUSEADDR, &opt, sizeof(opt));

    struct sockaddr_in addr = {0};
    addr.sin_family = AF_INET;
    addr.sin_port = htons(9090);
    addr.sin_addr.s_addr = INADDR_ANY;

    bind(sock, (struct sockaddr*)&addr, sizeof(addr));
    listen(sock, 5);

    while (!srv->shutting_down) {
        int client = accept(sock, NULL, NULL);
        if (client < 0) continue;
        handle_client(srv, client);
        close(client);
    }

    close(sock);
    free(srv);
    return 0;
}
